parameters.jsonBody:
={{ JSON.stringify({
  contents: [{
    parts: [{
      text: (() => {
        const report = $json.trendAnalysis ? JSON.parse($json.trendAnalysis) : $json;
        const niche = report.niche || '';
        const twConcepts = (report.twitterDerivedConcepts || []).slice(0, 5).join('\n- ');
        const topDirs    = (report.topDesignDirections    || []).slice(0, 5).join('\n- ');
        const emerging   = (report.emergingTrends         || []).slice(0, 5).join('\n- ');
        const unsaturated= (report.underservedOpportunities || []).slice(0, 3).join('\n- ');
        const audiences  = (report.audienceSegments       || []).slice(0, 5).join(', ');
        const colors     = (report.recurringColors        || []).slice(0, 5).join(', ');
        const typo       = (report.typographyStyles       || []).slice(0, 3).join(', ');
        const icons      = (report.illustrations          || []).slice(0, 8).join(', ');
        const season     = report.seasonality || {};
        return `You are a creative director for a print-on-demand t-shirt brand.

== TREND BRIEF: ${niche} ==

TOP DESIGN DIRECTIONS:
- ${topDirs}

TWITTER-DERIVED CONCEPTS (slang/memes to inspire from):
- ${twConcepts}

EMERGING TRENDS:
- ${emerging}

UNDERSERVED OPPORTUNITIES:
- ${unsaturated}

AUDIENCE SEGMENTS: ${audiences}
RECURRING COLORS: ${colors}
TYPOGRAPHY STYLES: ${typo}
ICONS & ILLUSTRATIONS: ${icons}
SEASONALITY: best months=${( season.bestMonths||[]).join(', ')}, direction=${season.direction||'stable'}

== YOUR TASK ==
Generate EXACTLY 10 original t-shirt design concepts.

DIVERSITY RULES (strictly enforce):
- Concepts 1-3: inspired by Twitter slang/memes above (culturally current)
- Concepts 4-6: based on underserved opportunities (low competition angles)
- Concepts 7-8: seasonal or emerging trend plays
- Concepts 9-10: timeless evergreen designs for this niche
- Mix tones: at least 2 motivational, 2 ironic, 1 raw, 1 minimalist, 1 bold
- Each must target a DIFFERENT audience segment
- No two concepts can share the same phrase or visual approach

Each imagePrompt must be detailed enough for an AI image generator:
include style, layout, colors, typography style, specific graphic elements,
background treatment, and print technique (e.g. screen print, distressed).

Return ONLY a JSON array of exactly 10 objects. No markdown, no code fences.
Shape per object:
{
  "id": 1,
  "title": "",
  "concept": "",
  "targetAudience": "",
  "sellingAngle": "",
  "tone": "motivational|ironic|raw|minimalist|bold|humorous",
  "phrase": "",
  "imagePrompt": "",
  "colors": [],
  "typography": "",
  "icons": [],
  "source": "twitter|opportunity|seasonal|evergreen"
}`;
      })()
    }]
  }],
  generationConfig: { temperature: 0.85, maxOutputTokens: 4000 }
}) }}

parameters.jsCode:
const raw = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
const clean = raw.replace(/```json|```/g, '').trim();
const match = clean.match(/\[[\s\S]*\]/);
let concepts = [];
try { concepts = JSON.parse(match?.[0] || '[]'); } catch (_) {}

const input = $('Execute Workflow Trigger').first().json;
const report = input.trendAnalysis ? JSON.parse(input.trendAnalysis) : input;
const niche = report.niche || '';

return [{ json: { niche, concepts } }];
